<script setup lang="ts">import{Archive,ArchiveRestore,Pin}from"lucide-vue-next";import type{ChatDetail}from"~/types/chat";defineProps<{conversation:ChatDetail;busy:boolean}>();defineEmits<{pin:[];archive:[]}>();const{tr}=useAppPreferences();</script>
<template><header class="flex items-center gap-3 border-b p-4"><span class="grid size-10 place-items-center rounded-full bg-brand-100 font-black">{{(conversation.contact.name||conversation.contact.phone)[0]}}</span><div class="min-w-0"><b class="block truncate text-sm">{{conversation.contact.name||conversation.contact.phone}}</b><small :class="conversation.session.status==='CONNECTED'?'text-emerald-500':'text-red-400'">{{conversation.session.displayName}} · {{conversation.session.status}}</small></div><div class="ms-auto flex shrink-0 gap-2"><button class="icon-btn" :class="conversation.isPinned?'bg-brand-50 text-brand-600':''" :disabled="busy" :title="conversation.isPinned?tr('برداشتن سنجاق','Unpin'):tr('سنجاق کردن','Pin')" @click="$emit('pin')"><Pin :size="17"/></button><button class="icon-btn" :disabled="busy" :title="conversation.isArchived?tr('خارج کردن از بایگانی','Unarchive'):tr('بایگانی','Archive')" @click="$emit('archive')"><component :is="conversation.isArchived?ArchiveRestore:Archive" :size="17"/></button></div></header></template>
